where.if:
and exists (
    select 1
    from ipe_ops.device_instance d
    where d.id = r.device_id

        and d.device_type = #{deviceType}


        and d.station_id = #{stationId}

)

mapper.select:
select 
from ipe_ops.alarm_record
where rule_id = #{ruleId}
  and device_id = #{deviceId}
  and channel_no = #{channelNo}
  and state = #{state}
order by last_at desc
limit 1

select 
from ipe_ops.alarm_record
where device_id = #{deviceId}
  and state = #{state}
order by last_at desc

select 
from ipe_ops.alarm_record
where state = #{state}
order by last_at desc
limit #{limit}

select 
from ipe_ops.alarm_record r

order by ${orderBy}
limit #{limit} offset #{offset}

select count(*)
from ipe_ops.alarm_record
where state = #{state}
  and level = #{level}
